import{_ as e,o as a,c as s,ag as i}from"./chunks/framework.CZxGLIO_.js";const k=JSON.parse('{"title":"Rooster","description":"本地进程守护、Cron 定时任务与 Agent HTTP API。","frontmatter":{"title":"Rooster","description":"本地进程守护、Cron 定时任务与 Agent HTTP API。"},"headers":[],"relativePath":"docs/rooster/index.md","filePath":"docs/rooster/index.md"}'),o={name:"docs/rooster/index.md"};function d(r,t,n,l,h,p){return a(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="rooster" tabindex="-1">Rooster <a class="header-anchor" href="#rooster" aria-label="Permalink to &quot;Rooster&quot;">​</a></h1><p>Rooster 将本地 Web 控制台、原生托盘、SQLite 执行记录和进程管理集中在一处。适合管理开发服务、后台进程、备份与同步脚本。</p><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><p>准备 Go 1.25+、Node.js 与 pnpm：</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/leancodebox/rooster.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rooster</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ..</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/roosterd</span></span></code></pre></div><p>默认打开 <code>http://127.0.0.1:9090</code>。端口占用时会尝试后续 100 个端口，以启动日志中的 <code>rooster ready</code> 地址为准。原生托盘入口为 <code>go run ./cmd/rooster</code>，需要平台对应的 Fyne 图形开发依赖。</p><h2 id="选择任务类型" tabindex="-1">选择任务类型 <a class="header-anchor" href="#选择任务类型" aria-label="Permalink to &quot;选择任务类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>类型</th><th>适用场景</th><th>行为</th></tr></thead><tbody><tr><td>常驻任务 <code>resident</code></td><td>开发服务、后台进程</td><td>支持失败重启、始终重启或不重启，以及指数退避</td></tr><tr><td>定时任务 <code>scheduled</code></td><td>备份、同步、巡检</td><td>五字段 Cron，可跳过重叠执行或允许并行</td></tr></tbody></table><p>创建后先手动运行一次，检查执行历史与日志，再启用自动运行。停用定时任务仅停止未来调度，不会终止正在运行的命令；必要时单独停止执行。编辑或删除任务前，需停用任务并等待活动执行结束。</p><h2 id="数据与运行环境" tabindex="-1">数据与运行环境 <a class="header-anchor" href="#数据与运行环境" aria-label="Permalink to &quot;数据与运行环境&quot;">​</a></h2><ul><li><code>ROOSTER_LISTEN</code>：首选监听地址，默认 <code>127.0.0.1:9090</code>。</li><li><code>ROOSTER_DATA_DIR</code>：数据目录，默认位于系统用户配置目录的 <code>Rooster</code> 下。</li><li>数据库为 <code>rooster.db</code>，日志保存在 <code>logs/</code>；迁移或备份时需保留数据目录。</li><li>支持工作目录、自定义 Shell、环境变量和执行日志。</li></ul><h2 id="agent-接入" tabindex="-1">Agent 接入 <a class="header-anchor" href="#agent-接入" aria-label="Permalink to &quot;Agent 接入&quot;">​</a></h2><table tabindex="0"><thead><tr><th>接口</th><th>用途</th></tr></thead><tbody><tr><td><code>GET /api/health</code></td><td>健康检查</td></tr><tr><td><code>GET /api/skill</code></td><td>Agent 操作指导</td></tr><tr><td><code>GET /api/docs</code></td><td>完整接口字段、响应和示例</td></tr></tbody></table><p>控制台顶部的「Agent 接入」可复制当前实例地址和文档。API 接受执行请求不等于任务执行成功，需要继续检查执行历史。</p><p>服务默认仅监听回环地址，没有远程认证层；任务以 Rooster 进程的用户权限执行。请保持本地访问。</p><p><a href="https://github.com/leancodebox/rooster" target="_blank" rel="noreferrer">源码与完整说明</a> · <a href="https://github.com/leancodebox/rooster/blob/main/docs/architecture.md" target="_blank" rel="noreferrer">架构</a></p>`,16)])])}const g=e(o,[["render",d]]);export{k as __pageData,g as default};
